// 2026-10-20 (Claude B). Time words and the locative -o (RULE-053, RULE-042,
// docs/HANDOFF_CLAUDE_B_20261019_temporal_locative.md, NV-104/107/171/174,
// PO ruling 2026-10-20). A time word in an event sentence takes locative -o,
// never object -ko; the sentence's real object keeps its own -ko. Isolated
// (citation) forms are the base. `now` = Da·o already ends in -o. `-de` is
// contrast/emphasis only and is never generated by default. Evidence class
// for tomorrow/now event forms: PO-stated native confirmation 2026-10-20
// (Da·o = "right now", an immediate temporal locative needing no extra -o;
// Knalo = "on tomorrow"); no raw Thangseng message on file.
export const TIME_ADVERB_FORMS = {
  today: { base: 'Da·al', event: 'Da·alo' },
  yesterday: { base: 'Mijal', event: 'Mijalo' },
  tomorrow: { base: 'Knal', event: 'Knalo' },
  now: { base: 'Da·o', event: 'Da·o' },
};
export const isTimeAdverb = (w) => Object.prototype.hasOwnProperty.call(TIME_ADVERB_FORMS, w);
const EVENT_FORMS = [...new Set(Object.values(TIME_ADVERB_FORMS).map(f => f.event))];
// If `garo` starts with an event time form followed by a space, split it off.
export function splitLeadingTimeForm(garo) {
  for (const f of EVENT_FORMS) {
    if (garo.startsWith(f + ' ')) return { time: f, rest: garo.slice(f.length + 1) };
  }
  return null;
}
